mapper.select:
SELECT COUNT(*)
FROM teams




    AND delete_flag = ${@com.uit.sociuscoremodules.shared.enums.DeleteFlagEnums@NOT_DELETED.value}

SELECT id, team_code, team_name, department_code, created_at, updated_at, deleted_at, delete_flag FROM teams
AND delete_flag = ${@com.uit.sociuscoremodules.shared.enums.DeleteFlagEnums@NOT_DELETED.value}
ORDER BY
LIMIT #{limit}
OFFSET #{offset}

mapper.update:
UPDATE teams
SET team_name = #{team.teamName},
    department_code = #{team.departmentCode},
    updated_at = CURRENT_TIMESTAMP
WHERE id = #{team.id}
  AND delete_flag = ${@com.uit.sociuscoremodules.shared.enums.DeleteFlagEnums@NOT_DELETED.value}

mapper.select:
SELECT EXISTS(
    SELECT 1
    FROM teams
    WHERE team_code = #{teamCode}
      AND delete_flag = ${@com.uit.sociuscoremodules.shared.enums.DeleteFlagEnums@NOT_DELETED.value}
)

mapper.sql:
LEFT JOIN team_employees te ON t.team_code = te.team_code
    AND te.delete_flag = ${@com.uit.sociuscoremodules.shared.enums.DeleteFlagEnums@NOT_DELETED.value}
LEFT JOIN employees e ON te.employee_id = e.client_id
    AND e.delete_flag = ${@com.uit.sociuscoremodules.shared.enums.DeleteFlagEnums@NOT_DELETED.value}
